const input = $input.first().json;
const execution = input.execution && typeof input.execution === 'object' ? input.execution : {};
const workflow = input.workflow && typeof input.workflow === 'object' ? input.workflow : {};
const error = execution.error && typeof execution.error === 'object'
  ? execution.error
  : input.error && typeof input.error === 'object'
    ? input.error
    : {};

const message = error.message || input.message || 'Unknown workflow error';
const nodeName = execution.lastNodeExecuted || error.node?.name || null;
const workflowName = workflow.name || 'Unknown workflow';
const executionUrl = execution.url || null;

const summary = nodeName
  ? workflowName + ' failed at ' + nodeName + ': ' + message
  : workflowName + ' failed: ' + message;

return [{
  json: {
    severity: 'error',
    summary,
    workflow: {
      id: workflow.id || null,
      name: workflowName,
    },
    execution: {
      id: execution.id || null,
      url: executionUrl,
      mode: execution.mode || null,
      lastNodeExecuted: nodeName,
    },
    error: {
      name: error.name || null,
      message,
      description: error.description || null,
    },
    alert: {
      title: 'n8n workflow failure: ' + workflowName,
      text: summary + (executionUrl ? '\n' + executionUrl : ''),
    },
    meta: { formattedAt: new Date().toISOString() },
  },
}];
